// Run Once for All Items mode

function normalizeVolumeUnit(unit) {
  const map = {
    'l': 'l', 'liter': 'l', 'liters': 'l', 'litre': 'l', 'litres': 'l',
    'ml': 'ml', 'milliliter': 'ml', 'milliliters': 'ml',
    'm3': 'm3', 'cubic meter': 'm3', 'cubic meters': 'm3', 'cbm': 'm3',
    'cubic foot': 'cubic_foot', 'cubic feet': 'cubic_foot', 'ft3': 'cubic_foot',
    'gallon': 'gallon_us', 'gallons': 'gallon_us', 'gal': 'gallon_us', 'us gallon': 'gallon_us',
    'ig': 'gallon_us', // imperial gallons: no native support, mapped to US gallons as nearest fallback
    'bbl': 'bbl', 'barrel': 'bbl', 'barrels': 'bbl'
  };
  return map[unit.toLowerCase().trim()] || unit.toLowerCase().trim();
}

function normalizeEnergyUnit(unit) {
  const map = {
    'kwh': 'kWh', 'kw h': 'kWh', 'kilowatt hour': 'kWh', 'kilowatt hours': 'kWh',
    'mwh': 'MWh', 'wh': 'Wh', 'gj': 'GJ', 'mj': 'MJ', 'btu': 'Btu'
  };
  return map[unit.toLowerCase().trim()] || unit;
}

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const entries = item.json.entries || [];

  if (item.json.parseError) {
    // Skip items where Parse AI Response failed to extract JSON
    continue;
  }

  let fileName = "unknown";
  try {
    const matched = $('Format for Climatiq1').itemMatching(i);
    const binKey = Object.keys(matched.binary || {})[0];
    if (binKey) fileName = matched.binary[binKey].fileName || "unknown";
  } catch (e) {}

  for (const entry of entries) {
    let activityId = "";
    let parameters = {};

    if (entry.type === "electricity") {
      activityId = "electricity-supply_grid-source_residual_mix";
      parameters = { energy: entry.value, energy_unit: normalizeEnergyUnit(entry.unit) };
    } else if (entry.type === "water") {
      activityId = "water_supply-type_na";
      parameters = { volume: entry.value, volume_unit: normalizeVolumeUnit(entry.unit) };
    } else if (entry.type === "fuel") {
      activityId = "fuel-type_motor_gasoline-fuel_use_na";
      parameters = { volume: entry.value, volume_unit: normalizeVolumeUnit(entry.unit) };
    }

    results.push({
      json: {
        sourceFile: fileName,
        type: entry.type || "unknown",
        companey_name: entry.companey_name || "Unknown",
        amount: entry.amount ?? null,
        currency: entry.currency || null,
        emission_factor: { activity_id: activityId, data_version: "^37" },
        parameters: parameters
      }
    });
  }
}

return results;

return $input.all().map((item, index) => {
  const apiData = item.json;
  const formatItems = $('Format for Climatiq').all();
  const originalData = (formatItems[index] && formatItems[index].json) || {};

  return {
    json: {
      type: originalData.type || "unknown",
      company_name: originalData.companey_name || "Unknown",
      consumption_value: apiData.activity_data.activity_value,
      consumption_unit: apiData.activity_data.activity_unit,
      cost_amount: originalData.amount || null,
      currency: originalData.currency || null,
      total_co2e: parseFloat(apiData.co2e.toFixed(2)),
      co2e_unit: apiData.co2e_unit,
      emission_region: apiData.emission_factor.region
    }
  };
});

const items = $input.all();
const returnData = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryPropertyName = Object.keys(item.binary)[0];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryPropertyName);

  returnData.push({
    json: {
      base64Data: buffer.toString('base64'),
      mimeType: item.binary[binaryPropertyName].mimeType
    },
    binary: item.binary
  });
}

return returnData;

return $input.all().map(item => {
  let entries = [];
  let parseError = null;

  try {
    const parts = item.json.candidates[0].content.parts;

    // Find the actual answer part — skip any "thought" parts if present,
    // grab the first part that has real text content.
    const answerPart = parts.find(p => p.text && !p.thought);

    if (!answerPart) {
      throw new Error('No text part found in response');
    }

    const parsed = JSON.parse(answerPart.text);
    entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);

  } catch (e) {
    parseError = e.message;
  }

  return {
    json: {
      entries,
      parseError
    }
  };
});

