={{ JSON.stringify({
  systemInstruction: {
    parts: [{
      text: "You are a strict, highly accurate AI Data Extraction Auditor for corporate ESG reporting. Analyze the attached invoice, receipt, or bill and extract consumption data. The document is typically an Electricity, Water, or Fuel (gas station) bill. Rules: 1) Electricity - look for Electricity or Consumption with units in kWh, this is Scope 2. 2) Water - look for Water or Water Consumption with units in IG, Gallons, or m3, this is Scope 3. 3) Fuel - look for Petrol, Super 98, Special 95, or Diesel with units in L, Liters, or Litres, this is Scope 1; ignore food or store items on the receipt. 4) If a bill contains multiple utility types, such as a DEWA bill with both electricity and water, return one entry per type. 5) If a clear consumption unit like kWh, m3, L, or IG is not stated but a total amount paid is visible, return that amount instead with unit set to money and infer the ISO currency code from context such as country or currency symbol."
    }]
  },
  contents: [{
    role: "user",
    parts: [
      { text: "Extract the consumption data from the attached document." },
      { inlineData: { mimeType: $json.mimeType, data: $json.base64Data } }
    ]
  }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 2048,
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        entries: {
          type: "ARRAY",
          items: {
            type: "OBJECT",
            properties: {
              type: { type: "STRING", enum: ["electricity", "water", "fuel"] },
              value: { type: "NUMBER" },
              unit: { type: "STRING" },
              currency: { type: "STRING" },
              scope: { type: "STRING" },
              companey_name: { type: "STRING" },
              amount: { type: "NUMBER" }
            },
            required: ["type", "value", "unit"]
          }
        }
      },
      required: ["entries"]
    }
  }
}) }}
